                isinstance(cell, (str, bytes))
                or not isinstance(cell, (tuple, list))
                or len(cell) != 2
            ):
                raise ValueError(
                    f"invalid obstacle {_describe_obstacle(cell)!s}: "
                    "each obstacle must be an (x, y) pair of two integers"
